// Cloudflare entry point: wraps the OpenNext worker to add the Cron Triggers
// declared in wrangler.jsonc. Bundled by wrangler, not by Next (see tsconfig).
// .open-next/worker.js is generated by `opennextjs-cloudflare build`.
import handler from "./.open-next/worker.js";

export {
  BucketCachePurge,
  DOQueueHandler,
  DOShardedTagCache,
} from "./.open-next/worker.js";

type Env = { CRON_SECRET?: string };
type Ctx = { waitUntil(promise: Promise<unknown>): void };

// Cron expression (wrangler.jsonc → triggers.crons) → job in /api/cron/[job].
// Same times the old node-cron scheduler used, in UTC.
const JOBS: Record<string, string> = {
  "0 * * * *": "recurring-invoices",
  "0 10 * * *": "onboarding-emails",
  "30 * * * *": "schedule",
};

export default {
  fetch: handler.fetch,

  async scheduled(event: { cron: string }, env: Env, ctx: Ctx) {
    const job = JOBS[event.cron];
    if (!job) {
      console.error(`[cron] no job for "${event.cron}"`);
      return;
    }
    const request = new Request(`https://orgaflow.dev/api/cron/${job}`, {
      method: "POST",
      headers: { authorization: `Bearer ${env.CRON_SECRET ?? ""}` },
    });
    ctx.waitUntil(
      handler.fetch(request, env, ctx).then(async (res: Response) => {
        if (!res.ok) {
          console.error(`[cron] ${job}: ${res.status} ${await res.text()}`);
        }
      }),
    );
  },
};
